def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_m, last_o = history[-1]

    opp_d = 0
    opp_c = 0
    my_d = 0
    for i in range(n):
        m, o = history[i]
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1
        else:
            opp_c += 1

    opp_streak_d = 0
    i = n - 1
    while i >= 0:
        if history[i][1] == 'D':
            opp_streak_d += 1
            i -= 1
        else:
            break

    opp_streak_c = 0
    i = n - 1
    while i >= 0:
        if history[i][1] == 'C':
            opp_streak_c += 1
            i -= 1
        else:
            break

    recent_d = 0
    recent_c = 0
    start = 0 if n < 10 else n - 10
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_d += 1
        else:
            recent_c += 1

    myD_oppC = 0
    myD_oppD = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                myD_oppC += 1
            else:
                myD_oppD += 1

    if myD_oppC > 0 and myD_oppD == 0 and recent_c >= 3:
        return 'D'

    grace = 5 if opp_c >= 10 else 4

    if last_o == 'C':
        if my_d == 0 and n >= 20 and n <= 85 and recent_c >= 5 and opp_d <= max(10, int(n * 0.4)):
            return 'D'
        return 'C'

    if last_m == 'D':
        if opp_c == 0:
            return 'D'
        if myD_oppC == 0 and recent_d >= grace and opp_d > grace:
            return 'D'
        if recent_c >= 2 and opp_d <= max(grace, int(n * 0.4)):
            return 'C'
        if recent_d >= grace + 2 or opp_d >= max(grace + 1, int(n * 0.5)):
            return 'D'
        return 'C'

    if opp_d <= grace:
        return 'C'
    if opp_c == 0:
        return 'D'
    if myD_oppC == 0 and recent_d >= grace and opp_d > grace:
        return 'D'
    if opp_streak_d >= grace + 2 or recent_d >= grace + 2:
        return 'D'
    if opp_d >= max(grace + 1, int(n * 0.4)) and recent_d >= 5:
        return 'D'
    if opp_streak_c >= 2 or recent_c >= 6:
        return 'C'
    if recent_d >= 4 and opp_d >= max(grace + 2, int(n * 0.25)):
        return 'D'
    return 'C'
